function ChatPanel({ messages, setMessages, pages, isExtracting, onJumpToPage }) {
  const [draft, setDraft] = useState('');
  const sendMessage = (text = draft) => {
    if (!text.trim()) return;
    const result = isExtracting ? { text: 'I am still reading the document. Please ask again in a moment.', pages: [] } : answerQuestion(text, pages);
    setMessages((items) => [...items, { type: 'user', text: text.trim() }, { type: 'ai', text: result.text, pages: result.pages }]);
    setDraft('');
  };
  return <section className="chat-panel"><div className="chat-tools"><button aria-label="Share">⇧</button><button aria-label="Download">⇩</button><button aria-label="Info">ⓘ</button></div><div className="messages">{messages.map((message, index) => message.type === 'user' ? <div className="user-message" key={index}><div>{message.text}</div><time>10:24 AM</time></div> : <div className="ai-message" key={index}><div className="ai-avatar">✦</div><div className="ai-card"><p>{message.text}</p>{message.pages?.length ? message.pages.map((pageNumber) => <button type="button" className="source-chip" key={pageNumber} onClick={() => onJumpToPage(pageNumber)}>▣ &nbsp;Source: Page {pageNumber}</button>) : message.source ? <span className="source-chip">▣ &nbsp;{message.source}</span> : null}<time>10:24 AM</time></div></div>)}<div className="suggested"><h3><Icon>✦</Icon> Suggested questions</h3>{suggestions.map((item) => <button key={item} onClick={() => sendMessage(item)}><Icon>◯</Icon>{item}</button>)}</div></div><form className="chat-input" onSubmit={(event) => { event.preventDefault(); sendMessage(); }}><button type="button" aria-label="Attach">⌕</button><input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Ask anything about this document..." /><button className="send-button" type="submit" aria-label="Send">➤</button></form></section>;
}

