function Overview({ setActive, openFile, records }) { const uploads = records.filter((item) => item.type === 'Uploaded'); const uniqueDocuments = [...new Map(uploads.map((item) => [item.name, item])).values()]; const summaries = records.filter((item) => item.type.startsWith('Summarised')).length; const comparisons = records.filter((item) => item.type === 'Compared').length; return <div className="page-content"><PageHeader eyebrow="Overview" title="Understand. Analyze. Transform." subtitle="Turn your documents into clear insights with AI-powered tools." action="New Analysis" onAction={openFile} /><div className="stats-grid"><StatCard icon="▣" value={uniqueDocuments.length} label="Documents uploaded" /><StatCard icon="▤" value={records.length} label="Total actions" /><StatCard icon="✦" value={summaries} label="Summaries generated" /><StatCard icon="◫" value={comparisons} label="Comparisons run" /></div><div className="section-title-row"><h2>Quick Actions</h2></div><div className="quick-grid">{[['intelligence','▣','Analyse Document','Extract insights'],['chat','◌','Chat with Document','Ask questions'],['summary','▤','Summarise','Get a shorter version'],['compare','◫','Compare','Find differences']].map(([id, icon, title, copy]) => <button className="quick-card" key={id} onClick={() => setActive(id)}><span className="quick-icon">{icon}</span><span><strong>{title}</strong><small>{copy}</small></span><b>›</b></button>)}</div><div className="two-column"><section className="panel"><div className="panel-heading"><h2>Recent Documents</h2><button onClick={() => setActive('history')}>View all</button></div>{uniqueDocuments.length ? uniqueDocuments.slice(0, 4).map((item) => <DocumentRow key={item.name} name={item.name} pages="—" status={item.status} date={item.date} />) : <div className="empty-state compact-empty"><div>▣</div><h2>No documents yet</h2><p>Upload a document to get started.</p></div>}</section><section className="panel"><div className="panel-heading"><h2>Recent Activity</h2></div>{records.length ? records.slice(0, 4).map((item, index) => <div className="activity-item" key={`${item.name}-${item.date}-${index}`}><i />{item.type} · {item.name}<time>{item.date}</time></div>) : <div className="empty-state compact-empty"><div>◴</div><h2>No activity yet</h2><p>Your actions will appear here.</p></div>}</section></div></div>; }
