function SummaryPage({ openFile, selectedFile, documentText, documentPages, fileError, onDrop, onSummary }) { const [type, setType] = useState('Detailed Summary'); const [length, setLength] = useState('Medium (~ 250 words)'); const [summaryText, setSummaryText] = useState(''); const [takeaways, setTakeaways] = useState([]); const label = selectedFile?.name || 'Select a document first'; const generate = () => { if (!selectedFile || !documentText) return; const pages = documentPages.length ? documentPages : [documentText]; const result = buildSummary(pages, type, length, selectedFile.name.toLowerCase().endsWith('.pdf') ? 'Page' : 'Part'); setSummaryText(result.text || 'No readable sentences were found in this document.'); setTakeaways(result.takeaways); onSummary(selectedFile.name, type); }; return <div className="page-content"><PageHeader eyebrow="Smart Summarizer" title="Long documents. Clear insights." subtitle="Generate concise and meaningful summaries from your files." action="Upload Document" onAction={openFile} /><div className="summary-grid"><section className="panel summary-controls"><div className="document-banner upload-mini" onClick={openFile} onDragOver={(event) => event.preventDefault()} onDrop={onDrop}><span className="pdf-badge">{selectedFile ? selectedFile.name.split('.').pop().toUpperCase() : 'FILE'}</span><div><strong>{label}</strong><small>{selectedFile ? `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB · selected locally` : 'Click to upload a PDF, DOCX or TXT'}</small></div></div>{fileError && <div className="file-error summary-error">{fileError}</div>}<h3>Summary Type</h3>{['Quick Summary','Detailed Summary','Bullet Points','Executive Summary','Chapter-wise'].map((x) => <label className={`radio-row ${type === x ? 'selected' : ''}`} key={x}><input type="radio" checked={type === x} onChange={() => { setType(x); setSummaryText(''); }} />{x}</label>)}<label className="field-label">Summary Length<select value={length} onChange={(event) => { setLength(event.target.value); setSummaryText(''); }}><option>Short (~ 100 words)</option><option>Medium (~ 250 words)</option><option>Long (~ 500 words)</option></select></label><button className="primary-button full-button" disabled={!selectedFile || !documentText} onClick={generate}>{summaryText ? 'Regenerate Summary' : 'Generate Summary'}</button></section><section className="panel result-panel"><div className="panel-heading"><h2>{summaryText ? `Summary (${type})` : 'Summary'}</h2><div><button disabled={!summaryText}>▢</button><button disabled={!summaryText}>⇩</button></div></div>{summaryText ? <><p className="generated-summary">{summaryText}</p><h3>Key Takeaways</h3>{takeaways.map((x) => <p className="check-line" key={x}>✓ {x}</p>)}</> : <div className="summary-empty"><div>✦</div><h3>{selectedFile ? (documentText ? 'Ready to summarise' : 'Waiting for document text') : 'Upload a document first'}</h3><p>{selectedFile ? 'Choose a summary format and generate a summary from the extracted text.' : 'The summary will be generated from your uploaded file.'}</p></div>}</section></div></div>; }
function Comparison({ onCompared }) { const [fileA, setFileA] = useState(null); const [fileB, setFileB] = useState(null); const [compared, setCompared] = useState(null); const [comparing, setComparing] = useState(false); const [error, setError] = useState(''); const inputA = useRef(null); const inputB = useRef(null); const pick = (ref) => ref.current?.click(); const choose = (event, setter) => { const file = event.target.files?.[0]; if (file) { setter(file); setCompared(null); setError(''); } }; const compare = async () => { if (!fileA || !fileB) return; setComparing(true); setError(''); try { const [textA, textB] = await Promise.all([extractDocumentText(fileA), extractDocumentText(fileB)]); const wordsA = new Set((textA.toLowerCase().match(/[a-z0-9]+/g) || [])); const wordsB = new Set((textB.toLowerCase().match(/[a-z0-9]+/g) || [])); const addedWords = [...wordsB].filter((word) => !wordsA.has(word)); const removedWords = [...wordsA].filter((word) => !wordsB.has(word)); const union = new Set([...wordsA, ...wordsB]).size; const common = [...wordsA].filter((word) => wordsB.has(word)).length; const linesA = textA.split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const linesB = textB.split(/\r?\n/).map((line) => line.trim()).filter(Boolean); const changedLines = linesB.filter((line) => !linesA.includes(line)).slice(0, 5); const result = { similarity: union ? Math.round((common / union) * 100) : 0, added: addedWords.length, removed: removedWords.length, modified: changedLines.length, additions: addedWords.slice(0, 8), removals: removedWords.slice(0, 8), changedLines }; setCompared(result); onCompared(fileA.name, fileB.name); } catch (comparisonError) { console.error('Comparison read error:', comparisonError); setError(`These documents could not be read for comparison (${comparisonError?.message || 'unknown error'}). Please try another PDF, DOCX or TXT file.`); } finally { setComparing(false); } }; const labelA = fileA?.name || 'Select first document'; const labelB = fileB?.name || 'Select second document'; return <div className="page-content"><PageHeader eyebrow="Document Comparison" title="See what changed." subtitle="Compare two documents and instantly identify differences." /><div className="compare-selectors"><button className="file-select uploadable" onClick={() => pick(inputA)}><span className="pdf-badge">{fileA ? fileA.name.split('.').pop().toUpperCase() : 'FILE'}</span><span><b>{labelA}</b><small>{fileA ? `${(fileA.size / 1024 / 1024).toFixed(2)} MB · selected locally` : 'Click to upload PDF, DOCX or TXT'}</small></span><span>⌄</span></button><input ref={inputA} hidden type="file" accept=".pdf,.doc,.docx,.txt" onChange={(event) => choose(event, setFileA)} /><button className="swap-button">⇄</button><button className="file-select uploadable" onClick={() => pick(inputB)}><span className="pdf-badge">{fileB ? fileB.name.split('.').pop().toUpperCase() : 'FILE'}</span><span><b>{labelB}</b><small>{fileB ? `${(fileB.size / 1024 / 1024).toFixed(2)} MB · selected locally` : 'Click to upload PDF, DOCX or TXT'}</small></span><span>⌄</span></button><input ref={inputB} hidden type="file" accept=".pdf,.doc,.docx,.txt" onChange={(event) => choose(event, setFileB)} /><button className="primary-button" disabled={!fileA || !fileB || comparing} onClick={compare}>{comparing ? 'Comparing…' : 'Compare'}</button></div>{error && <div className="compare-hint file-error">{error}</div>}{!fileA || !fileB ? <div className="compare-hint">Upload both documents above to enable comparison.</div> : compared && <div className="compare-hint success-note">Real comparison complete · based on extracted document text.</div>}<div className="two-column compare-panels"><section className="panel similarity-panel"><h2>Comparison Overview</h2><div className="similarity-circle">{compared ? `${compared.similarity}%` : '—'}<small>Similarity</small></div><div className="compare-stats"><b>{compared?.added ?? '—'}<small>Added</small></b><b>{compared?.removed ?? '—'}<small>Removed</small></b><b>{compared?.modified ?? '—'}<small>Changed lines</small></b></div></section><section className="panel"><h2>Major Changes</h2>{compared ? <ul className="change-list">{compared.additions.length ? <li><strong>Added words:</strong> {compared.additions.join(', ')}</li> : null}{compared.removals.length ? <li><strong>Removed words:</strong> {compared.removals.join(', ')}</li> : null}{compared.changedLines.length ? compared.changedLines.map((line) => <li key={line}>{line}</li>) : null}{!compared.additions.length && !compared.removals.length && !compared.changedLines.length ? <li>No text differences detected.</li> : null}</ul> : <p className="compare-placeholder">Upload both documents and click Compare to calculate real differences.</p>}</section></div></div>; }
function WritingStudio() { const [text, setText] = useState('The project was completed on time and the team worked very hard to ensure all the requirements were met.'); const [tone, setTone] = useState('Professional'); const improve = () => setText(tone === 'Professional' ? 'The project was delivered on schedule, with the team demonstrating strong dedication to meeting all requirements.' : 'The team finished the project on time and met every requirement.'); return <div className="page-content"><PageHeader eyebrow="Writing Studio" title="Make every word work better." subtitle="Rewrite, improve, simplify and transform your content with AI." /><div className="writing-toolbar"><label>Action<select><option>Rewrite</option><option>Simplify Text</option><option>Fix Grammar</option><option>Convert to Bullet Points</option></select></label><label>Tone<select value={tone} onChange={(e) => setTone(e.target.value)}><option>Professional</option><option>Friendly</option><option>Concise</option></select></label><button className="primary-button" onClick={improve}>Generate</button></div><div className="writing-grid"><section className="panel editor-panel"><div className="panel-heading"><h2>Original Text</h2><button>▢</button></div><textarea value={text} onChange={(e) => setText(e.target.value)} /><small>Words: {text.trim() ? text.trim().split(/\s+/).length : 0} · Characters: {text.length}</small></section><section className="panel editor-panel rewritten"><div className="panel-heading"><h2>Rewritten ({tone})</h2><button>▢</button></div><div className="rewrite-output">{text || 'Your improved text will appear here.'}</div><small>Demo output · Words: {text.trim() ? text.trim().split(/\s+/).length : 0}</small></section></div></div>; }
function History({ search, records }) { const filtered = records.filter((item) => item.name.toLowerCase().includes(search.toLowerCase()) || item.type.toLowerCase().includes(search.toLowerCase())); return <div className="page-content"><PageHeader eyebrow="History" title="Your recent work." subtitle="Find documents and actions from your LexiLab workspace." /><section className="panel history-panel">{filtered.length ? filtered.map((r, index) => <div className="history-row" key={`${r.name}-${r.date}-${index}`}><span className="pdf-badge">{r.extension || 'FILE'}</span><strong>{r.name}</strong><span>{r.type}</span><time>{r.date}</time><span className="status-pill">{r.status}</span></div>) : <div className="empty-state"><div>⌕</div><h2>No activity yet</h2><p>Upload a document or complete an analysis to see it here.</p></div>}</section></div>; }
function Settings({ onThemeChange }) { const [settings, setSettings] = useState(() => { try { return JSON.parse(localStorage.getItem('lexilab-settings') || '{"name":"R","theme":"Light","emailNotifications":true,"email":""}'); } catch (error) { return { name: 'R', theme: 'Light', emailNotifications: true, email: '' }; } }); const [saved, setSaved] = useState(false); const update = (key, value) => { setSettings((current) => ({ ...current, [key]: value })); if (key === 'theme') onThemeChange(value); setSaved(false); }; const save = (event) => { event.preventDefault(); localStorage.setItem('lexilab-settings', JSON.stringify(settings)); onThemeChange(settings.theme); setSaved(true); }; return <div className="page-content"><PageHeader eyebrow="Settings" title="Make LexiLab yours." subtitle="Manage your profile, preferences and notifications." /><form onSubmit={save}><div className="settings-grid"><section className="panel setting-card"><div className="setting-icon">♙</div><div className="setting-body"><h2>Profile settings</h2><p>Update your display name and workspace identity.</p><label className="setting-field">Display name<input value={settings.name} onChange={(event) => update('name', event.target.value)} /></label></div></section><section className="panel setting-card"><div className="setting-icon">⚙</div><div className="setting-body"><h2>Appearance</h2><p>Choose how LexiLab looks in this browser.</p><label className="setting-field">Theme<select value={settings.theme} onChange={(event) => update('theme', event.target.value)}><option>Light</option><option>Dark</option><option>System default</option></select></label></div></section><section className="panel setting-card"><div className="setting-icon">♧</div><div className="setting-body"><h2>Notifications</h2><p>Control local notification preferences.</p><label className="setting-check"><input type="checkbox" checked={settings.emailNotifications} onChange={(event) => update('emailNotifications', event.target.checked)} />Enable email notifications</label></div></section><section className="panel setting-card"><div className="setting-icon">▣</div><div className="setting-body"><h2>Account settings</h2><p>Store the email associated with this browser workspace.</p><label className="setting-field">Email address<input type="email" value={settings.email} onChange={(event) => update('email', event.target.value)} placeholder="you@example.com" /></label></div></section></div><div className="settings-actions"><button className="primary-button" type="submit">Save settings</button>{saved && <span className="success-note">Settings saved locally.</span>}</div></form></div>; }

function App() {
  const [active, setActive] = useState('chat'); const [collapsed, setCollapsed] = useState(false); const [search, setSearch] = useState(''); const [selectedFile, setSelectedFile] = useState(null); const [documentText, setDocumentText] = useState(''); const [isExtracting, setIsExtracting] = useState(false); const [fileError, setFileError] = useState(''); const fileInput = useRef(null); const [documentPages, setDocumentPages] = useState([]); const [currentPage, setCurrentPage] = useState(1); const [zoom, setZoom] = useState(100); const totalPages = documentPages.length || SAMPLE_PAGES.length; const goToPage = (n) => setCurrentPage(Math.min(Math.max(1, n), totalPages)); const changeZoom = (delta) => setZoom((z) => Math.min(200, Math.max(50, z + delta))); const [history, setHistory] = useState(() => { try { return JSON.parse(localStorage.getItem('lexilab-history') || '[]'); } catch (error) { return []; } }); const [theme, setTheme] = useState(() => { try { return JSON.parse(localStorage.getItem('lexilab-settings') || '{"theme":"Light"}').theme || 'Light'; } catch (error) { return 'Light'; } });
  const [messages, setMessages] = useState([{ type: 'ai', text: 'Ask me anything about the sample document, or upload your own PDF, DOCX or TXT file to chat with it.', source: 'LexiLab' }]);
  useEffect(() => { if (selectedFile) setMessages([{ type: 'ai', text: isExtracting ? `Reading ${selectedFile.name}…` : `Now chatting with ${selectedFile.name}. Ask a question about the uploaded document.`, source: isExtracting ? 'Preparing document' : 'Uploaded document' }]); }, [selectedFile, isExtracting]);
  useEffect(() => { localStorage.setItem('lexilab-history', JSON.stringify(history)); }, [history]);
  const addHistory = (name, type, status = 'Complete') => { const extension = name.split('.').pop().toUpperCase(); setHistory((items) => [{ name, type, status, extension, date: new Date().toLocaleString() }, ...items]); };
  const openFile = () => { setFileError(''); fileInput.current?.click(); }; const handleFile = async (file) => { if (!file) return; const allowed = ['pdf','doc','docx','txt']; const extension = file.name.split('.').pop().toLowerCase(); if (!allowed.includes(extension)) { setSelectedFile(null); setDocumentText(''); setFileError('Unsupported file type. Please choose a PDF, DOCX or TXT document.'); return; } if (file.size > 25 * 1024 * 1024) { setSelectedFile(null); setDocumentText(''); setFileError('This file is larger than 25MB. Please choose a smaller document.'); return; } setSelectedFile(file); setDocumentText(''); setDocumentPages([]); setCurrentPage(1); setZoom(100); setFileError(''); addHistory(file.name, 'Uploaded', 'Ready'); setIsExtracting(true); try { if (extension === 'pdf') { const pageTexts = await extractPdfPages(await file.arrayBuffer()); if (!pageTexts.some((text) => text.trim())) { setFileError('This PDF has no selectable text (it may be a scanned image), so it cannot be read in the browser.'); setSelectedFile(null); } else { setDocumentText(pageTexts.map((text, index) => `--- Page ${index + 1} ---\n${text}`).join('\n\n')); setDocumentPages(pageTexts); } } else if (extension === 'txt') { const raw = await file.text(); setDocumentText(raw); setDocumentPages(splitIntoPages(raw)); } else { const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() }); const raw = result.value || ''; setDocumentText(raw || 'No text was found in this DOCX file.'); setDocumentPages(splitIntoPages(raw)); } } catch (error) { console.error('Document read error:', error); setFileError(`We could not read this document in the browser (${error?.message || 'unknown error'}). Please try another PDF, DOCX or TXT file.`); } finally { setIsExtracting(false); } }; const handleDrop = (event) => { event.preventDefault(); handleFile(event.dataTransfer.files?.[0]); }; const pageTitle = active === 'chat' ? 'Chat with Documents' : navItems.find((item) => item[0] === active)?.[1] || 'Workspace';
  const page = active === 'overview' ? <Overview setActive={setActive} openFile={openFile} records={history} /> : active === 'intelligence' ? <Intelligence openFile={openFile} selectedFile={selectedFile} fileError={fileError} onDrop={handleDrop} /> : active === 'summary' ? <SummaryPage openFile={openFile} selectedFile={selectedFile} documentText={documentText} fileError={fileError} onDrop={handleDrop} documentPages={documentPages} onSummary={(name, type) => addHistory(name, `Summarised · ${type}`)} /> : active === 'compare' ? <Comparison onCompared={(a, b) => addHistory(`${a} vs ${b}`, 'Compared')} /> : active === 'writing' ? <WritingStudio /> : active === 'history' ? <History search={search} records={history} /> : active === 'settings' ? <Settings onThemeChange={setTheme} /> : <div className="workspace"><div className="workspace-heading"><div><p className="eyebrow">{pageTitle}</p><h1>Understand. Analyze. Transform.</h1><p className="subheading">Ask questions, discover insights and turn every document into clear next steps.</p></div><button className="primary-button" onClick={openFile}><Icon>＋</Icon>New analysis</button></div><div className="document-toolbar"><button className="document-select"><span className="pdf-badge">PDF</span>{selectedFile?.name || 'AI_History_Review.pdf'} <span>⌄</span></button><div className="page-control"><button type="button" aria-label="Previous page" disabled={currentPage <= 1} onClick={() => goToPage(currentPage - 1)}>‹</button><b>{currentPage}</b><span>/ {totalPages}</span><button type="button" aria-label="Next page" disabled={currentPage >= totalPages} onClick={() => goToPage(currentPage + 1)}>›</button></div><div className="zoom-control"><button type="button" aria-label="Zoom out" disabled={zoom <= 50} onClick={() => changeZoom(-10)}>−</button><span>{zoom}%</span><button type="button" aria-label="Zoom in" disabled={zoom >= 200} onClick={() => changeZoom(10)}>＋</button></div></div><div className="content-grid"><section className="preview-panel"><div className="preview-scroll"><DocumentPage documentFile={selectedFile} documentText={documentText} documentPages={documentPages} currentPage={currentPage} zoom={zoom} isExtracting={isExtracting} /></div></section><ChatPanel messages={messages} setMessages={setMessages} pages={documentPages.length ? documentPages : SAMPLE_PAGES} isExtracting={isExtracting} onJumpToPage={goToPage} /></div></div>;
  const darkMode = theme === 'Dark' || (theme === 'System default' && window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches); return <div className={`app-shell ${darkMode ? 'theme-dark' : ''}`}><Sidebar active={active} setActive={setActive} collapsed={collapsed} setCollapsed={setCollapsed} /><main className="main-content"><header className="topbar"><div className="mobile-title"><div className="brand-mark"><span>⌬</span></div><b>LexiLab</b></div><label className="search-box"><Icon>⌕</Icon><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search documents..." /></label><div className="top-actions"><button aria-label="Notifications">♧<span className="notification-dot" /></button><button className="avatar" aria-label="Open profile">R</button></div></header><input ref={fileInput} type="file" accept=".pdf,.doc,.docx,.txt" hidden onChange={(event) => handleFile(event.target.files?.[0])} />{page}</main></div>;
}

export default App;
